import React from 'react';
import { ChevronDown, Smartphone, Laptop, Tablet, Watch, Headphones, Camera } from 'lucide-react';

const categories = [
  { name: 'Electronics', icon: Laptop },
  { name: 'Smartphones', icon: Smartphone },
  { name: 'Tablets', icon: Tablet },
  { name: 'Wearables', icon: Watch },
  { name: 'Audio', icon: Headphones },
  { name: 'Camera', icon: Camera },
];

const CategoryNav = () => {
  return (
    <div className="bg-white shadow-sm border-b border-gray-200">
      <div className="max-w-7xl mx-auto px-4">
        <div className="flex items-center space-x-6 overflow-x-auto py-3 scrollbar-hide">
          {/* All Categories */}
          <div className="flex items-center space-x-1 text-gray-700 hover:text-blue-600 cursor-pointer whitespace-nowrap">
            <span className="font-semibold">All</span>
            <ChevronDown size={16} />
          </div>

          {/* Category Links */}
          {categories.map((category, index) => {
            const Icon = category.icon;
            return (
              <div 
                key={index}
                className="flex items-center space-x-2 text-gray-600 hover:text-blue-600 cursor-pointer whitespace-nowrap"
              >
                <Icon size={18} />
                <span className="text-sm">{category.name}</span>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default CategoryNav;
